  c.fillStyle = lin(c, 0, 0, CW, CH, ['rgba(255,255,255,0)', 'rgba(255,255,255,.10)', 'rgba(255,255,255,0)', 'rgba(255,255,255,.06)', 'rgba(255,255,255,0)']); c.fillRect(0, 0, CW, CH);
  { const hx = 22; c.globalAlpha = 0.32; c.fillStyle = lin(c, 0, 0, 0, CH, ['#ff5ad8', '#5ad8ff', '#7aff9a', '#ffe85a', '#ff7a5a', '#c87aff']); c.fillRect(hx, 140, 8, CH - 260); c.globalAlpha = 0.5; c.fillStyle = '#fff'; for (let y = 150; y < CH - 130; y += 22) c.fillRect(hx + 2, y, 4, 2); c.globalAlpha = 1; }
  c.fillStyle = 'rgba(0,0,0,.22)'; for (let x = 60; x < CW - 40; x += 18) { c.beginPath(); c.arc(x, 4, 2.4, 0, 7); c.fill(); }
  c.restore();
  // doppelter Zierrand mit Eck-Ornamenten
  c.save(); c.shadowColor = 'rgba(0,0,0,.35)'; c.shadowBlur = 6; rr(c, 8, 8, CW - 16, CH - 16, 30); c.lineWidth = 6; c.strokeStyle = lin(c, 0, 0, CW, CH, ['#fff2b0', '#c8952e', '#fff6d0', '#a8701a']); c.stroke(); c.restore();
  c.save(); rr(c, 17, 17, CW - 34, CH - 34, 24); c.lineWidth = 2; c.strokeStyle = th.rim || 'rgba(255,255,255,.75)'; c.stroke(); c.restore();
  for (const [x, y] of [[17, 17], [CW - 17, 17], [17, CH - 17], [CW - 17, CH - 17]]) { c.save(); c.translate(x, y); star(c, 0, 0, 3, 9, 4, 0); c.fillStyle = '#fff2b0'; c.fill(); c.restore(); }
  // Preis-Stern links oben
