  T(c, short(def.price).replace(' €', ''), 86, 74, def.price < 100 ? 34 : 44, { fill: '#fff', w: 900 }); T(c, 'EURO', 86, 108, 15, { fill: '#fff6c8', w: 700 });
  // Titel
