  const art = mk(); const foil = mk(); const out = mk(); const mat = mk(); const ax = art.getContext('2d'); const fx = foil.getContext('2d'); const ox = out.getContext('2d'); const mx = mat.getContext('2d');
  const st = { card, revealed: new Set(), assign: {}, used: 0, k: 0, done: false, fell: false, tease: [], locked: new Set(), result: null };
  const CELL = 8; const GW = CW / CELL; const GH = CH / CELL; const cleared = new Uint8Array(GW * GH);
  const cells = F.map((f) => { const L2 = []; for (let gy = Math.floor(f.y / CELL); gy <= Math.floor((f.y + f.h) / CELL); gy++) for (let gx = Math.floor(f.x / CELL); gx <= Math.floor((f.x + f.w) / CELL); gx++) { const px = gx * CELL + CELL / 2; const py = gy * CELL + CELL / 2; const inside = f.circle ? Math.hypot(px - cx(f), py - cy(f)) < f.w / 2 - 3 : px > f.x + 3 && px < f.x + f.w - 3 && py > f.y + 3 && py < f.y + f.h - 3; if (inside && gx >= 0 && gy >= 0 && gx < GW && gy < GH) L2.push(gy * GW + gx); } return L2; });
